<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { io } from 'socket.io-client';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { api, role, label, time } from './api';
import DocumentView from './DocumentView.vue';
import ReviewNotice from './ReviewNotice.vue';
const router=useRouter(), route=useRoute(), contract=ref(), run=ref(), catalog=ref([]), tags=ref([]), selectedId=ref(''), filter=ref('all'), versionId=ref(''), reviewId=ref(''), busy=ref(false), error=ref('');
const classification=ref({typeId:'',tags:[],perspectiveConfirmed:false}), background=ref({}), showContext=ref(false), showDecision=ref(false), showReturn=ref(false), showArchive=ref(false), showManual=ref(false), showFeedback=ref(false), versionKind=ref('contract'), reason=ref(''), suggestion=ref(''), action=ref('accept'), severity=ref('medium'), feedbackText=ref(''), feedbackKind=ref('rule'), returnReason=ref('');
const decision=ref({outcome:'agree',reason:'',conditions:''}), archive=ref({manuallyReturned:false,note:'',signedVersionId:''}), manual=ref({title:'',severity:'medium',reason:'',suggestion:'',evidence:[]});
const editor=ref(false), compare=ref(false), annotationMode=ref('side'); let officeEditor, timer, socket, loading=false;
const decisionRevision=ref(0),reviewers=ref([]),assignee=ref(null);
function openDecision(){decisionRevision.value=contract.value.revision;showDecision.value=true;}
async function saveAssignment(){await operation(()=>api(`/contracts/${contract.value.id}/assignment`,{method:'PUT',body:{revision:contract.value.revision,reviewerId:assignee.value}}));}
const version=computed(()=>contract.value?.versions.find(v=>v.id===versionId.value)), previous=computed(()=>contract.value?.versions.find(v=>v.id===version.value?.parent_id));
const selected=computed(()=>run.value?.findings.find(f=>f.id===selectedId.value));
const unresolved=computed(()=>run.value?.findings.filter(f=>f.check_status!=='pass' && (!f.disposition || f.disposition.action==='needs_information')).length||0);
const findings=computed(()=>run.value?.findings.filter(f=>filter.value==='all'||filter.value==='open'?!((filter.value==='open')&&(f.check_status==='pass'||f.disposition&&f.disposition.action!=='needs_information')):f.severity===filter.value)||[]);
const current=computed(()=>run.value?.isCurrent && versionId.value===contract.value?.current_version_id);
const isTrial=computed(()=>run.value?.snapshot?.reviewMode==='trial');
const trialAvailable=computed(()=>catalog.value.flatMap(c=>c.types).find(t=>t.id===contract.value?.classification?.typeId)?.trialAvailable||false);
const editable=computed(()=>role('legal')&&current.value&&contract.value?.legal_status!=='returned'&&run.value?.status==='completed'&&!run.value.decision);
const evidence=computed(()=>selected.value?.evidence||[]);
const annotations=computed(()=>run.value?.findings||[]);
watch(selectedId,()=>{ if(selected.value) selectFinding(selected.value); });
const typeName=id=>catalog.value.flatMap(c=>c.types).find(t=>t.id===id)?.name||'待分类';
async function refresh(quiet=false){if(loading)return;loading=true;try{const c=await api('/contracts/'+route.params.id,{quiet});contract.value=c;versionId.value ||= c.current_version_id;reviewId.value ||= c.current_review_id;if(reviewId.value)run.value=await api('/reviews/'+reviewId.value,{quiet});if(!selectedId.value)selectedId.value=run.value?.findings?.find(f=>f.check_status!=='pass')?.id||run.value?.findings?.[0]?.id;error.value='';}catch(e){error.value=e.message;}finally{loading=false;}}
async function operation(fn){if(busy.value)return;busy.value=true;try{await fn();await refresh();ElMessage.success('已保存');}finally{busy.value=false;}}
function selectFinding(f){selectedId.value=f.id;reason.value=f.disposition?.reason||'';suggestion.value=f.disposition?.suggestion??f.suggestion;action.value=f.disposition?.action||'accept';severity.value=f.disposition?.severity||f.severity;}
async function selectRun(){run.value=await api('/reviews/'+reviewId.value);versionId.value=run.value.version_id;selectedId.value='';if(run.value.findings.length)selectFinding(run.value.findings[0]);}
async function openContext(){if(role('legal'))reviewers.value=await api('/reviewers');assignee.value=contract.value.reviewer_id;background.value={...contract.value.background};classification.value={typeId:contract.value.classification?.typeId||'',tags:[...(contract.value.classification?.tags||[])],perspectiveConfirmed:false};showContext.value=true;}
async function saveBackground(){await operation(async()=>{await api(`/contracts/${contract.value.id}/background`,{method:'PATCH',body:{background:background.value,revision:contract.value.revision}});reviewId.value='';versionId.value='';});}
async function confirmClassification(){let archiveResult;await operation(async()=>{const result=await api(`/contracts/${contract.value.id}/classification`,{method:'PUT',body:{...classification.value,revision:contract.value.revision}});archiveResult=result.archive;reviewId.value='';showContext.value=false;});if(archiveResult?.status==='archived')ElMessage.success(`分类已确认，附件已归档到：${archiveResult.path}`);else if(archiveResult?.status==='failed')ElMessage.warning(archiveResult.message);}
async function uploadVersion(e){const file=e.target.files[0];if(!file)return;await operation(async()=>{const data=new FormData();data.set('file',file);data.set('revision',contract.value.revision);data.set('kind',versionKind.value);await api(`/contracts/${contract.value.id}/versions`,{method:'POST',body:data});if(versionKind.value==='contract'){versionId.value='';reviewId.value='';selectedId.value='';}});e.target.value='';}
async function newRun(mode='formal'){await operation(async()=>{const value=await api('/reviews',{method:'POST',body:{contractId:contract.value.id,revision:contract.value.revision,mode}});reviewId.value=value.reviewId;versionId.value=contract.value.current_version_id;selectedId.value='';});}
async function disposition(){await operation(()=>api(`/reviews/${run.value.id}/findings/${selected.value.id}/disposition`,{method:'PUT',body:{revision:selected.value.revision,action:action.value,reason:reason.value,...(suggestion.value!==selected.value.suggestion?{suggestion:suggestion.value}:{}),...(severity.value!==selected.value.severity?{severity:severity.value}:{})}}));}
async function finalize(){await operation(async()=>{await api(`/reviews/${run.value.id}/decision`,{method:'POST',body:{...decision.value,revision:decisionRevision.value}});showDecision.value=false;});}
async function sendBack(){await operation(async()=>{await api(`/reviews/${run.value.id}/return`,{method:'POST',body:{reason:returnReason.value,revision:contract.value.revision}});showReturn.value=false;});}
async function saveArchive(){await operation(async()=>{await api(`/contracts/${contract.value.id}/archive`,{method:'POST',body:{...archive.value,...(!archive.value.signedVersionId?{signedVersionId:undefined}:{}),revision:contract.value.revision}});showArchive.value=false;});}
async function addManual(){await operation(async()=>{await api(`/reviews/${run.value.id}/findings`,{method:'POST',body:manual.value});showManual.value=false;});}
async function saveFeedback(edit=false){
  await operation(async()=>{
    const feedback=await api('/feedback-cases',{method:'POST',body:{reviewId:run.value.id,...(selected.value?{findingId:selected.value.id}:{}),kind:feedbackKind.value,content:feedbackText.value}});
    showFeedback.value=false;feedbackText.value='';
    if(edit) await router.push({path:'/feedback',query:{feedback:feedback.id,edit:'1'}});
  });
}
async function openEditor(){try{const value=await api(`/contracts/${contract.value.id}/editor`);editor.value=true;await nextTick();if(!window.DocsAPI)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=value.serverUrl+'/web-apps/apps/api/documents/api.js';script.onload=resolve;script.onerror=reject;document.head.appendChild(script);});officeEditor?.destroyEditor();officeEditor=new window.DocsAPI.DocEditor('office-editor',{...value.config,width:'100%',height:'780px',events:{onDocumentStateChange:()=>{}}});}catch{editor.value=false;ElMessage.error('编辑器不可用，请检查服务配置，或在本机 Word 修改后上传。');}}
function closeEditor(){officeEditor?.destroyEditor();officeEditor=null;editor.value=false;refresh();}
watch(()=>route.params.id,()=>{contract.value=null;reviewId.value='';versionId.value='';refresh();});
onMounted(async()=>{const cat=await api('/catalog');catalog.value=cat.categories;tags.value=cat.tags;await refresh();socket=io({withCredentials:true});socket.on('connect',()=>socket.emit('join-contract',route.params.id));socket.on('review-progress',()=>refresh(true));timer=setInterval(()=>refresh(true),6000);});
onUnmounted(()=>{clearInterval(timer);socket?.disconnect();officeEditor?.destroyEditor();});
</script>
<template>
  <div v-if="!contract" class="empty-state">{{ error||'正在加载合同…' }}</div>
  <template v-else>
    <div v-if="contract.legal_status===`returned` && contract.returns?.length" class="notice danger">退回理由：{{ contract.returns[0].reason }}。当前预审已冻结，请上传修改版本或创建新的预审任务后继续处理。</div>
    <div class="detail-heading"><div><router-link to="/" class="back-link">← 返回合同台账</router-link><h1>{{ contract.title }}</h1><div class="metadata"><span class="mono">{{ contract.number }}</span><span>{{ contract.source==='dingtalk'?'钉钉审批':'手动上传' }}</span><span class="badge" :class="contract.legal_status">{{ label(contract.legal_status) }}</span></div></div><div class="action-row"><button @click="openContext">分类与业务背景</button><button v-if="role('legal','business')" @click="newRun()" :disabled="busy">正式重新预审</button><button v-if="role('legal','business')&&trialAvailable" @click="newRun('trial')" :disabled="busy">示例规则试审</button><button v-if="editable&&!isTrial" class="primary" @click="openDecision">确认最终结论</button><button v-if="role('legal')&&run?.decision&&current" class="primary" @click="showArchive=true">人工回传与归档</button></div></div>
    <div v-if="isTrial" class="notice">示例规则试审 · 使用内置参考检查项，尚未经公司法务发布确认。可核对原文、复核风险和下载带标记的报告；最终结论需发布正式规则后重新预审。</div><div class="review-summary"><span><b>{{ typeName(contract.classification?.typeId) }}</b><span class="badge" :class="contract.classification?.confirmed?'confirmed':'waiting_input'">{{ contract.classification?.confirmed?'分类已确认':'分类待确认' }}</span></span><span>当前文件 <b>v{{ contract.versions.find(v=>v.id===contract.current_version_id)?.version_no }}</b></span><span>待处理 <b :class="unresolved?'error-text':''">{{ unresolved }}</b> 项</span><span>规则覆盖 <b v-if="run?.coverage.totalRules">{{ run.coverage.checkedRules||0 }}/{{ run.coverage.totalRules }}</b><b v-else-if="run?.snapshot.rules?.length">本次计划 {{ run.snapshot.rules.length }} 项</b><b v-else>尚未执行条款审查</b></span><span class="muted">{{ label(run?.status) }} {{ run?.progress||0 }}%</span></div>
    <ReviewNotice v-if="run?.error_message" :run="run" :classification-name="current ? typeName(contract.classification?.typeId) : ''" :can-supplement="role('legal','business') && current" @background="openContext" :can-confirm="role('legal') && current && contract.legal_status !== 'returned'" :can-try="role('legal','business') && current && trialAvailable" :busy="busy" :can-view-rules="role('legal','publisher')" @classification="openContext" @trial="newRun('trial')" /><div v-if="run&&!current" class="notice">正在查看历史文件或预审记录。处理意见和结论保留在对应版本中。</div><div v-if="run?.decision" class="notice success"><b>法务最终结论：{{ label(run.decision.outcome) }}</b><span> {{ run.decision.conditions||run.decision.reason }} · {{ time(run.decision.created_at) }}</span></div>
    <div class="version-bar"><label>预审记录 <select v-model="reviewId" @change="selectRun"><option v-for="r in contract.reviews" :value="r.id" :key="r.id">{{ time(r.created_at) }} · {{ r.snapshot?.reviewMode==='trial'?'示例试审':'正式预审' }} · {{ label(r.status) }}{{ r.id===contract.current_review_id?' · 当前':'' }}</option></select></label><label>原文版本 <select v-model="versionId"><option v-for="v in contract.versions" :value="v.id" :key="v.id">v{{ v.version_no }} · {{ v.filename }}{{ v.kind==='signed'?' · 签署件':v.kind==='supplement'?' · 补充材料':'' }}</option></select></label><label v-if="previous?.parsed" class="inline-check"><input type="checkbox" v-model="compare" />标记与上一版本的内容差异</label><div v-if="run" class="annotation-mode" role="group" aria-label="原文建议显示方式"><span>建议显示</span><button :class="{active:annotationMode==='side'}" @click="annotationMode='side'">旁批</button><button :class="{active:annotationMode==='color'}" @click="annotationMode='color'">彩色标记</button><button :class="{active:annotationMode==='plain'}" @click="annotationMode='plain'">仅原文</button></div><a v-if="run" :href="`/api/reviews/${run.id}/report?format=docx`">下载报告 DOCX ↗</a><a v-if="run" :href="`/api/reviews/${run.id}/report`">HTML ↗</a></div>
    <div class="review-grid">
      <section class="risk-column panel"><div class="panel-heading"><h2>审查清单 <span class="count">{{ run?.findings.length||0 }}</span></h2><button v-if="editable" class="text-btn" @click="showManual=true">＋ 补充</button></div><div class="risk-filters"><button v-for="f in [{id:'all',name:'全部'},{id:'open',name:'未处理'},{id:'high',name:'高风险'}]" :key="f.id" :class="{selected:filter===f.id}" @click="filter=f.id">{{ f.name }}</button></div><div class="risk-list"><button v-for="f in findings" :key="f.id" class="risk-item" :class="{active:selectedId===f.id}" @click="selectFinding(f)"><div><span class="severity-dot" :class="f.check_status==='pass'?'pass':f.severity"></span><b>{{ f.title }}</b></div><p>{{ f.reason }}</p><span class="badge" :class="f.check_status==='pass'?'completed':f.severity">{{ f.check_status==='pass'?'符合':label(f.severity) }}</span><small>{{ f.disposition?label(f.disposition.action):label(f.check_status) }}</small></button><div v-if="!findings.length" class="empty-state compact"><h3>{{ run?.status==='completed'?'没有符合条件的检查项':'尚未生成审查结果' }}</h3><p>{{ run?.error_message||'任务进度与异常会在这里显示。' }}</p></div></div><details class="step-list"><summary>处理步骤与快照</summary><p v-for="s in run?.steps" :key="s.id">{{ s.stage }} · {{ label(s.status) }}</p><pre>{{ run?.snapshot }}</pre></details></section>
      <section class="original-column panel"><div class="original-actions"><span>合同原文 <small v-if="annotationMode!=='plain'">· 建议已定位到对应条款</small></span><div><button v-if="role('legal')&&version?.filename.endsWith('.docx')&&versionId===contract.current_version_id" @click="editor?closeEditor():openEditor()">{{ editor?'关闭编辑器':'在线编辑' }}</button><template v-if="role('business','legal')"><select v-model="versionKind"><option value="contract">上传修改版本</option><option value="supplement">上传补充材料</option><option value="signed">上传已签署件</option></select><label class="button-file">选择文件<input type="file" accept=".pdf,.docx" @change="uploadVersion" :disabled="busy" /></label></template></div></div><div v-if="editor" id="office-editor"></div><DocumentView v-else :version="version" :evidence="versionId===run?.version_id?evidence:[]" :findings="versionId===run?.version_id?annotations:[]" :annotation-mode="annotationMode" :previous="compare?previous:null" @select-finding="selectedId=$event" /></section>
      <section class="evidence-column panel"><div class="panel-heading"><h2>证据与复核</h2></div><div v-if="selected" class="evidence-body"><div class="eyebrow">{{ selected.rule_id }}</div><h3>{{ selected.title }}</h3><span class="badge" :class="selected.severity">{{ label(selected.severity) }}</span><h4>原文证据</h4><blockquote v-for="(e,i) in selected.evidence" :key="i"><span class="mono">{{ e.blockId }}</span>{{ e.quote }}</blockquote><div v-if="!selected.evidence.length" class="notice">{{ selected.kind==='missing'?'全文检查范围内未发现所需条款。缺失项没有原文或页码。':'该项无法确定，请结合全文人工核实。' }}</div><h4>AI 判断</h4><p class="prewrap">{{ selected.reason }}</p><h4>规则与法律依据</h4><p>{{ run.snapshot.rules?.find(r=>r.id===selected.rule_id)?.instruction||'法务人工补充' }}</p><blockquote v-for="k in selected.legal_refs" :key="k.id"><b>{{ k.title }}</b><p>{{ k.content }}</p><small>{{ k.source }} · {{ k.effectiveDate }}</small></blockquote><p v-if="!selected.legal_refs.length" class="muted">未引用可追溯的法律资料，需法务核实依据。</p><h4>修改建议</h4><p class="prewrap">{{ selected.suggestion||'无修改建议' }}</p><form v-if="editable" class="stack disposition" @submit.prevent="disposition"><h4>法务处理</h4><select v-model="action"><option v-for="a in ['accept','reject','correct','needs_information','acknowledge']" :key="a" :value="a">{{ label(a) }}</option></select><label>风险等级<select v-model="severity"><option v-for="s in ['high','medium','low']" :key="s" :value="s">{{ label(s) }}</option></select></label><label>处理理由<textarea v-model="reason" rows="3" :required="selected.check_status==='uncertain'||action!=='accept'||severity!==selected.severity||suggestion!==selected.suggestion" placeholder="驳回、修正或确认不确定项时填写理由" /></label><label>修正建议<textarea v-model="suggestion" rows="3" /></label><button class="primary" :disabled="busy">保存复核意见</button></form><div v-else-if="selected.disposition" class="notice">{{ label(selected.disposition.action) }} · {{ selected.disposition.reason||'已采纳' }}</div><div class="action-row"><button v-if="role('legal','publisher')" @click="showFeedback=true">沉淀反馈案例</button><button v-if="role('legal')&&current&&!run.decision" @click="showReturn=true">退回修改 / 补件</button></div></div><div v-else class="empty-state compact"><span class="empty-icon">⌕</span><h3>选择检查项查看依据</h3><p>风险、原文引用和人工处理会在此关联展示。</p><button v-if="role('legal')&&current" @click="showReturn=true">退回补充材料</button></div></section>
    </div>
    <el-dialog v-model="showContext" title="分类与业务背景" width="620px"><div class="stack"><label>我方主体<input v-model="background.ourEntity" /></label><label>我方立场<input v-model="background.perspective" /></label><label>交易目的<textarea v-model="background.purpose" rows="3" /></label><button v-if="role('business','legal')" @click="saveBackground" :disabled="busy">保存背景并重新预审</button><hr /><template v-if="role('legal')"><label>分配法务<select v-model="assignee"><option :value="null">未分配</option><option v-for="u in reviewers" :key="u.id" :value="u.id">{{ u.displayName }} · {{ u.department }}</option></select></label><button @click="saveAssignment" :disabled="busy">保存分配</button><label>主要合同类型<select v-model="classification.typeId"><optgroup v-for="c in catalog" :key="c.id" :label="c.name"><option v-for="t in c.types" :key="t.id" :value="t.id">{{ t.name }}{{ t.reviewEnabled?'（已发布规则）':t.trialAvailable?'（可示例试审）':'（待配置规则）' }}</option></optgroup></select></label><div class="tag-options"><label v-for="tag in tags" :key="tag"><input type="checkbox" :value="tag" v-model="classification.tags" />{{ tag }}</label></div><label class="inline-check"><input type="checkbox" v-model="classification.perspectiveConfirmed" />已核实本版本合同类型、我方主体与交易立场</label><button class="primary" @click="confirmClassification" :disabled="busy||!classification.typeId||!classification.perspectiveConfirmed">确认分类及立场</button></template><p v-else class="muted">分类与立场由法务确认。</p></div></el-dialog>
    <el-dialog v-model="showDecision" title="确认最终法务结论" width="540px"><form class="stack" @submit.prevent="finalize"><div class="notice">结论绑定此文件版本与预审记录。未处理风险、不确定项或未确认分类会阻止确认。</div><label>最终结论<select v-model="decision.outcome"><option v-for="o in ['agree','conditional','disagree']" :key="o" :value="o">{{ label(o) }}</option></select></label><label>条件<textarea v-model="decision.conditions" :required="decision.outcome==='conditional'" rows="3" /></label><label>理由<textarea v-model="decision.reason" :required="decision.outcome==='disagree'" rows="3" /></label><button class="primary" :disabled="busy">确认并保存结论</button></form></el-dialog>
    <el-dialog v-model="showReturn" title="退回修改或补件" width="500px"><form @submit.prevent="sendBack" class="stack"><label>退回理由<textarea v-model="returnReason" required rows="5" /></label><button class="primary" :disabled="busy">确认退回</button></form></el-dialog>
    <el-dialog v-model="showArchive" title="人工回传与归档" width="540px"><form class="stack" @submit.prevent="saveArchive"><div class="notice">先下载终稿与审核报告，人工回传钉钉。本操作不代表线下签署完成。</div><a :href="`/api/files/${contract.current_version_id}?download=1`">下载审核终稿 ↗</a><label>关联签署件<select v-model="archive.signedVersionId"><option value="">尚未上传签署件</option><option v-for="v in contract.versions.filter(v=>v.kind==='signed')" :key="v.id" :value="v.id">v{{ v.version_no }} · {{ v.filename }}</option></select></label><label>归档备注<textarea v-model="archive.note" rows="3" /></label><label class="inline-check"><input type="checkbox" v-model="archive.manuallyReturned" required />已人工回传最终意见和终稿至来源审批</label><button class="primary" :disabled="busy">记录回传并归档</button></form></el-dialog>
    <el-dialog v-model="showManual" title="补充人工风险" width="520px"><form class="stack" @submit.prevent="addManual"><label>检查项名称<input v-model="manual.title" required /></label><label>风险等级<select v-model="manual.severity"><option v-for="s in ['high','medium','low']" :key="s" :value="s">{{ label(s) }}</option></select></label><label>问题及处理理由<textarea v-model="manual.reason" required rows="4" /></label><label>修改建议<textarea v-model="manual.suggestion" rows="3" /></label><button class="primary" :disabled="busy">添加人工风险</button></form></el-dialog>
    <el-dialog v-model="showFeedback" title="提交候选反馈" width="520px"><form class="stack" @submit.prevent="saveFeedback(false)"><div class="notice">反馈保存后可直接修改规则；只有确认发布后，新标准才用于后续预审。</div><select v-model="feedbackKind"><option value="rule">规则调整建议</option><option value="false_positive">误报案例</option><option value="false_negative">漏报案例</option><option value="normal_expression">正常表达</option><option value="classification">分类纠错</option></select><textarea v-model="feedbackText" required rows="6" /><div class="dialog-actions"><button :disabled="busy">仅保存反馈</button><button v-if="feedbackKind!=='normal_expression'" type="button" class="primary" :disabled="busy||!feedbackText.trim()" @click="saveFeedback(true)">{{ feedbackKind==='classification'?'保存并修改分类标准':'保存并修改规则' }}</button></div></form></el-dialog>
  </template>
</template>
